/* ==UserStyle==
@name         Stylish Car Animation Theme
@namespace    USO Archive
@version      1.0.0
@description  A dark theme featuring a continuous animated sports car moving across the screen.
@author       AI Assistant
==/UserStyle== */

body {
    background-color: #0f111a !important;
    overflow-x: hidden !important;
    position: relative;
}

/* Create the road container */
body::before {
    content: "";
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 40px;
    background: #1a1c23;
    border-top: 4px solid #3b82f6; /* Neon blue top edge for the road */
    z-index: 9998;
    pointer-events: none;
}

/* Create the animated car */
body::after {
    content: "?️"; /* CSS Emoji Car - Easy, lightweight, and works on all sites */
    font-size: 32px;
    position: fixed;
    bottom: 12px;
    left: -50px;
    z-index: 9999;
    pointer-events: none;
    animation: driveCar 8s linear infinite;
}

/* Driving Animation */
@keyframes driveCar {
    0% {
        left: -10%;
        transform: scaleX(1); /* Facing right */
    }
    49% {
        transform: scaleX(1);
    }
    50% {
        left: 110%;
        transform: scaleX(-1); /* Turn around facing left */
    }
    99% {
        transform: scaleX(-1);
    }
    100% {
        left: -10%;
        transform: scaleX(1);
    }
}
